import sys
data = sys.stdin.read().split()
n, K = int(data[0]), int(data[1])
adj = [[] for _ in range(n + 1)]
for i in range(n - 1):
    u, v = int(data[2 + 2 * i]), int(data[3 + 2 * i])
    adj[u].append(v)
    adj[v].append(u)
removed = [False] * (n + 1)
par = [0] * (n + 1)
sz = [0] * (n + 1)
ans = 0
stack = [1]
while stack:                                       # one iteration per component; no recursion
    r = stack.pop()
    comp = [r]
    par[r] = 0
    for v in comp:                                 # BFS the current component
        for to in adj[v]:
            if not removed[to] and to != par[v]:
                par[to] = v
                comp.append(to)
    total = len(comp)
    for v in comp:
        sz[v] = 1
    for v in reversed(comp):
        if par[v]:
            sz[par[v]] += sz[v]
    c = r                                          # walk towards any child holding more than half the vertices
    while True:
        nxt = 0
        for to in adj[c]:
            if not removed[to] and to != par[c] and sz[to] * 2 > total:
                nxt = to
                break
        if not nxt:
            break
        c = nxt
    cnt = [0] * (total + 1)                        # cnt[d] = vertices at depth d seen so far (the centroid is depth 0)
    cnt[0] = 1
    for to in adj[c]:
        if removed[to]:
            continue
        q = [(to, c, 1)]
        depths = []
        for v, p, d in q:
            depths.append(d)
            if 0 <= K - d <= total:
                ans += cnt[K - d]                  # pairs through c that use this subtree and an earlier one
            for nb in adj[v]:
                if not removed[nb] and nb != p:
                    q.append((nb, v, d + 1))
        for d in depths:                           # add this subtree only after counting against the earlier ones
            cnt[d] += 1
    removed[c] = True
    for to in adj[c]:
        if not removed[to]:
            stack.append(to)
