const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], K = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < n - 1; i++) { const u = tok[2 + 2 * i], v = tok[3 + 2 * i]; adj[u].push(v); adj[v].push(u); }
const removed = new Array(n + 1).fill(false), par = new Array(n + 1).fill(0), sz = new Array(n + 1).fill(0);
let ans = 0;
const stack = [1];
while (stack.length) {
  const r = stack.pop();
  const comp = [r];
  par[r] = 0;
  for (let i = 0; i < comp.length; i++) {
    const v = comp[i];
    for (const to of adj[v]) if (!removed[to] && to !== par[v]) { par[to] = v; comp.push(to); }
  }
  const total = comp.length;
  for (const v of comp) sz[v] = 1;
  for (let i = total - 1; i >= 0; i--) if (par[comp[i]]) sz[par[comp[i]]] += sz[comp[i]];
  let c = r;
  for (;;) {
    let nxt = 0;
    for (const to of adj[c]) if (!removed[to] && to !== par[c] && sz[to] * 2 > total) { nxt = to; break; }
    if (!nxt) break;
    c = nxt;
  }
  const cnt = new Array(total + 1).fill(0);
  cnt[0] = 1;
  for (const first of adj[c]) {
    if (removed[first]) continue;
    const qv = [first], qp = [c], qd = [1];
    for (let i = 0; i < qv.length; i++) {
      const v = qv[i], p = qp[i], d = qd[i];
      if (K - d >= 0 && K - d <= total) ans += cnt[K - d];
      for (const nb of adj[v]) if (!removed[nb] && nb !== p) { qv.push(nb); qp.push(v); qd.push(d + 1); }
    }
    for (const d of qd) cnt[d]++;
  }
  removed[c] = true;
  for (const to of adj[c]) if (!removed[to]) stack.push(to);
}
