import java.io.*;
import java.util.*;

public class Main {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int K = (int) in.nval;
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(v);
            adj[v].add(u);
        }
        boolean[] removed = new boolean[n + 1];
        int[] par = new int[n + 1], sz = new int[n + 1], comp = new int[n], qv = new int[n], qp = new int[n], qd = new int[n];
        long ans = 0;
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(1);
        while (!stack.isEmpty()) {
            int r = stack.pop();
            int total = 0;
            comp[total++] = r;
            par[r] = 0;
            for (int i = 0; i < total; i++) {
                int v = comp[i];
                for (int to : adj[v]) if (!removed[to] && to != par[v]) { par[to] = v; comp[total++] = to; }
            }
            for (int i = 0; i < total; i++) sz[comp[i]] = 1;
            for (int i = total - 1; i >= 0; i--) if (par[comp[i]] != 0) sz[par[comp[i]]] += sz[comp[i]];
            int c = r;
            while (true) {
                int nxt = 0;
                for (int to : adj[c]) if (!removed[to] && to != par[c] && sz[to] * 2 > total) { nxt = to; break; }
                if (nxt == 0) break;
                c = nxt;
            }
            long[] cnt = new long[total + 1];
            cnt[0] = 1;
            for (int first : adj[c]) {
                if (removed[first]) continue;
                int qs = 0;
                qv[qs] = first; qp[qs] = c; qd[qs] = 1; qs++;
                for (int i = 0; i < qs; i++) {
                    int v = qv[i], p = qp[i], d = qd[i];
                    if (K - d >= 0 && K - d <= total) ans += cnt[K - d];
                    for (int nb : adj[v]) if (!removed[nb] && nb != p) { qv[qs] = nb; qp[qs] = v; qd[qs] = d + 1; qs++; }
                }
                for (int i = 0; i < qs; i++) cnt[qd[i]]++;
            }
            removed[c] = true;
            for (int to : adj[c]) if (!removed[to]) stack.push(to);
        }
        System.out.println(ans);
    }
}

