    vector<int> stack = {1};
    while (!stack.empty()) {
        int r = stack.back(); stack.pop_back();
        int total = 0;
        comp[total++] = r;
        par[r] = 0;
        for (int i = 0; i < total; i++) {
            int v = comp[i];
            for (int to : adj[v]) if (!removed[to] && to != par[v]) { par[to] = v; comp[total++] = to; }
        }
        for (int i = 0; i < total; i++) sz[comp[i]] = 1;
        for (int i = total - 1; i >= 0; i--) if (par[comp[i]]) sz[par[comp[i]]] += sz[comp[i]];
        int c = r;
        while (true) {
            int nxt = 0;
            for (int to : adj[c]) if (!removed[to] && to != par[c] && sz[to] * 2 > total) { nxt = to; break; }
            if (!nxt) break;
            c = nxt;
        }
        vector<long long> cnt(total + 1, 0);
        cnt[0] = 1;
